const crypto = require('crypto');
const canonical = v => Array.isArray(v) ? '['+v.map(canonical).join(',')+']' : v && typeof v === 'object' ? '{'+Object.entries(v).filter(([,x])=>x!==undefined).sort(([a],[b])=>a.localeCompare(b)).map(([k,x])=>JSON.stringify(k)+':'+canonical(x)).join(',')+'}' : JSON.stringify(v);
const envelope = $json.body;
const key = $env.GETDONE_N8N_SIGNING_KEY;
if (!key || key.length < 32 || !envelope || typeof envelope !== 'object') throw new Error('Missing trusted configuration');
const signature = $json.headers['x-getdone-signature'];
const expected = crypto.createHmac('sha256',key).update(canonical(envelope)).digest('hex');
if (typeof signature !== 'string' || !/^[a-f0-9]{64}$/.test(signature) || !crypto.timingSafeEqual(Buffer.from(expected,'hex'),Buffer.from(signature,'hex'))) throw new Error('Invalid signature');
if (!Number.isFinite(Date.parse(envelope.sentAt)) || Math.abs(Date.now()-Date.parse(envelope.sentAt)) > 60000 || !envelope.authorizationConsumptionHash || !envelope.idempotencyKey) throw new Error('Expired or unauthorized envelope');
const registrations = JSON.parse($env.GETDONE_N8N_ALLOWED_SCOPE_JSON || '[]');
const p = envelope.parameters;
const registration = registrations.find(c=>c.portfolioId===envelope.scope.portfolioId && c.companyId===envelope.scope.companyId && c.environment===envelope.scope.environment && c.connectionId===p.connectionId);
if (!registration || p.companyId!==registration.companyId) throw new Error('Tenant scope mismatch');
const workflow = $workflow.name;
if (workflow==='deployment_health') {
 if(envelope.capability!=='http.request' || Object.keys(p.payload || {}).length || p.operation!==registration.operation) throw new Error('Read-only deployment scope required');
 const url=new URL(registration.deploymentUrl);
 if(url.protocol!=='https:' || url.username || url.password || url.search || url.hash) throw new Error('Invalid registered deployment URL');
 return [{json:{envelope, deploymentUrl:url.toString()}}];
}
if(!registration.repositories?.includes(p.repository) || !/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(p.repository)) throw new Error('Repository is not allowlisted');
if(workflow==='github_create_branch') {
 if(envelope.capability!=='github.branch.create' || !/^[a-f0-9]{64}$/.test(envelope.previewHash || '') || !/^[a-f0-9]{40}$/.test(p.expectedSourceSha || '') || !/^(?!\/)(?!.*\.\.)(?!.*\/\/)[A-Za-z0-9._\/-]+$/.test(p.branch || '') || ['main','master',...(registration.protectedBranches || [])].includes(p.branch)) throw new Error('Invalid approved branch scope');
} else if(envelope.capability!=='github.repository.read' || !['repository','checks'].includes(p.operation)) throw new Error('Repository-health reads only');
return [{json:{envelope}}];

